package com.bank.streak;

import java.util.logging.Logger;

// Computes settlement success streaks for National Bank of India.
public class StreakService {
    private static final Logger log = Logger.getLogger(StreakService.class.getName());

    // Longest run of 1s (successful days). O(n), O(1).
    public int longestOnes(int[] days) {
        if (days == null) return 0;
        int current = 0;        // current run of successes
        int best = 0;           // best run seen
        for (int d : days) {
            if (d == 1) {
                current++;
                if (current > best) best = current;   // update immediately
            } else {
                current = 0;    // a failure breaks the streak
            }
        }
        final int result = best;
        log.info(() -> "Longest success streak = " + result + " days");
        return best;
    }

    // Longest run of 1s if up to k zeros may be treated as successes.
    // Sliding window: shrink from left when window holds more than k zeros.
    public int longestOnesWithFlips(int[] days, int k) {
        if (days == null) return 0;
        int left = 0, zeros = 0, best = 0;
        for (int right = 0; right < days.length; right++) {
            if (days[right] == 0) zeros++;
            while (zeros > k) {              // too many failures in window
                if (days[left] == 0) zeros--;
                left++;                      // shrink from the left
            }
            int windowLen = right - left + 1;
            if (windowLen > best) best = windowLen;
        }
        final int result = best;
        log.info(() -> "Longest streak allowing " + k + " fixes = " + result + " days");
        return best;
    }
}
