package com.bank.streak;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: compute settlement success streaks for Rajesh.
public class StreakDemo {
    private static final Logger log = Logger.getLogger(StreakDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        StreakService service = new StreakService();

        // Rajesh (SAV2001) settlement outcomes: 1=success, 0=failure.
        int[] days = {1, 1, 0, 1, 1, 1, 0, 1, 1};
        int plain = service.longestOnes(days);
        log.info(() -> "Rajesh longest success streak: " + plain + " days");

        int withOneFix = service.longestOnesWithFlips(days, 1);
        log.info(() -> "With up to 1 allowed fix: " + withOneFix + " days");
    }
}
